import unicodedata


def code_theme(nom, pris):
    """« 01.01 Reporting scope (BP-1) » → « 01_01_Reporting_scope_BP_1 », unique dans le référentiel."""
    base = unicodedata.normalize("NFKD", nom).encode("ascii", "ignore").decode()
    base = re.sub(r"[^A-Za-z0-9]+", "_", base).strip("_")[:36] or "Theme"
    code, i = base, 2
    while code in pris:
        code, i = f"{base}_{i}", i + 1
    pris.add(code)
    return code


def creer_referentiel(apps, schema_editor):
    """Un référentiel « Reporting RSE <structure> » avec l'arbre des thèmes et sous-thèmes actuels (ordre alphabétique,
    comme l'affichage d'avant), un élément par KPI (même ordre), les traductions du glossaire des thèmes."""
    KPI = apps.get_model("referentiel", "KPI")
    if not KPI.objects.exists():
        return
    Instance = apps.get_model("parametres", "Instance")
    Referentiel, Theme = apps.get_model("referentiel", "Referentiel"), apps.get_model("referentiel", "Theme")
    Element, Glossaire = apps.get_model("referentiel", "ElementReferentiel"), apps.get_model("parametres", "TraductionTheme")
    i = Instance.objects.filter(pk=1).first()
    nom = f"Reporting RSE {i.nom}" if i and i.nom else "Reporting RSE"
    ref = Referentiel.objects.create(code="RSE", nom=nom, couleur=(i.couleur_principale if i else "#1F5FAD"), ordre=1)
    glossaire = {}
    for g in Glossaire.objects.all():
        glossaire.setdefault(g.texte, {})[g.langue] = {"nom": g.traduction}
    pris, themes, sous = set(), {}, {}
    couples = sorted(set(KPI.objects.values_list("theme", "sous_theme")))
    for t in sorted({t for t, _ in couples if t}):
        themes[t] = Theme.objects.create(referentiel=ref, code=code_theme(t, pris), nom=t, ordre=len(themes) + 1,
                                         traductions=glossaire.get(t, {}))
    for t, st in couples:
        if t and st and (t, st) not in sous:
            n = sum(1 for (t2, _) in sous if t2 == t) + 1
            sous[(t, st)] = Theme.objects.create(referentiel=ref, parent=themes[t], code=code_theme(st, pris), nom=st, ordre=n,
                                                 traductions=glossaire.get(st, {}))
    elements = []
    for k in KPI.objects.all():
        theme = sous.get((k.theme, k.sous_theme)) or themes.get(k.theme)
        if theme is None and k.sous_theme:  # sous-thème sans thème : rangé à la racine
            theme = themes.setdefault(f"\x00{k.sous_theme}", Theme.objects.create(
                referentiel=ref, code=code_theme(k.sous_theme, pris), nom=k.sous_theme, ordre=len(themes) + 1))
        elements.append(Element(referentiel=ref, theme=theme, kpi_id=k.code, ordre=k.ordre))
    Element.objects.bulk_create(elements, batch_size=500)


